/// Look an icon up by its design-document id, e.g. `"a-files"`.
///
/// Linear over ~3 dozen entries. The shell resolves an icon once when it builds the atlas,
/// not per frame, so a map would be machinery for a cost nothing pays.
pub fn find(id: &str) -> Option<&'static IconSet> {
    ICONS.iter().find(|i| i.id == id)
}

/// The index into [`SIZES`] for `px`, or None if the set is not rasterized at that size.
pub fn size_index(px: usize) -> Option<usize> {
    SIZES.iter().position(|&s| s == px)
}
